//!
//! `inside` reproduces `RegularGridInterpolator(arange grids, values, method="linear")` at one point
//! with scipy's operation order (find_indices + _evaluate_linear), so every `> 0.5` decision, and
//! with it the search path, is bit-identical to the Python version.

use numpy::ndarray::{Array1, ArrayView3, Ix3};
use numpy::{IntoPyArray, PyArrayDyn, PyReadonlyArrayDyn};
use pyo3::exceptions::PyValueError;
use pyo3::prelude::*;

struct Grid<'a> {
    vals: ArrayView3<'a, u8>,
    shape: [usize; 3],
    /// shape - 1 per axis, the last grid coordinate
    upper: [f64; 3],
}

impl Grid<'_> {
    /// The Python `is_inside` body for the point `c`.
    fn inside(&self, c: &[f64; 3]) -> PyResult<bool> {
        if c.iter().any(|&x| x < 0.0) || (0..3).any(|d| c[d] > self.upper[d]) {
            return Ok(false);
        }
        // NaN passes both checks above; scipy's bounds check then rejects it
        if let Some(d) = (0..3).find(|&d| c[d].is_nan()) {
            return Err(PyValueError::new_err(format!("One of the requested xi is out of bounds in dimension {d}")));
        }
        let mut idx = [[0usize; 2]; 3];
        let mut w = [[0.0f64; 2]; 3];
        for d in 0..3 {
            // scipy find_indices: size-1 axes use index -1 (wraps to 0) and distance 0
            let (lo, hi, y) = if self.shape[d] == 1 {
                (0, 0, 0.0)
            } else {
                // c in [0, n-1]; the interval is closed on the right, so c == n-1 uses n-2
                let i = if c[d] >= self.upper[d] { self.shape[d] - 2 } else { c[d].floor() as usize };
                (i, i + 1, c[d] - i as f64)
            };
            idx[d] = [lo, hi];
            w[d] = [1.0 - y, y];
        }
        // _evaluate_linear: hypercube corners in itertools.product order, weight = ((1*w0)*w1)*w2,
        // value = 0 + term + term ... ; zero-valued corners add +0.0 and are skipped
        let mut value = 0.0f64;
        for a in 0..2 {
            for b in 0..2 {
                for e in 0..2 {
                    let v = self.vals[[idx[0][a], idx[1][b], idx[2][e]]];
                    if v != 0 {
                        value += f64::from(v) * (w[0][a] * w[1][b] * w[2][e]);
                    }
                }
            }
        }
        Ok(value > 0.5)
    }
}

/// A 1-D float array broadcast to length 3 the way numpy would broadcast it against the others.
fn vec3(a: &PyReadonlyArrayDyn<'_, f64>, len: usize) -> [f64; 3] {
    let a = a.as_array();
    if len == 1 { [a[[0]]; 3] } else { [a[[0]], a[[1]], a[[2]]] }
}

#[pyfunction]
fn corner_bisection_search(
    py: Python<'_>,
    region: PyReadonlyArrayDyn<'_, u8>,
    start: PyReadonlyArrayDyn<'_, f64>,
    v1: PyReadonlyArrayDyn<'_, f64>,
    v2: PyReadonlyArrayDyn<'_, f64>,
    delta: f64,
) -> PyResult<Option<Py<PyArrayDyn<f64>>>> {
    let vals = region.as_array().into_dimensionality::<Ix3>().map_err(|_| PyValueError::new_err("region must be 3D"))?;
    let (n0, n1, n2) = vals.dim();
    let lens = [&start, &v1, &v2].map(|a| { let a = a.as_array(); if a.ndim() == 1 { a.len() } else { usize::MAX } });
    let n = lens.iter().copied().filter(|&l| l != 1).max().unwrap_or(1);
    if n != 3 || lens.iter().any(|&l| l != 1 && l != n) {
        return Err(PyValueError::new_err(format!(
            "operands could not be broadcast together with shapes ({},) ({},) ({},)",
            lens[0], lens[1], lens[2]
        )));
    }
    let (s, v1, v2) = (vec3(&start, lens[0]), vec3(&v1, lens[1]), vec3(&v2, lens[2]));
    let grid = Grid { vals, shape: [n0, n1, n2], upper: [n0 as f64 - 1.0, n1 as f64 - 1.0, n2 as f64 - 1.0] };
    // start + a * v1 + b * v2, evaluated left to right as numpy does
    let point = |a: f64, b: f64| [s[0] + a * v1[0] + b * v2[0], s[1] + a * v1[1] + b * v2[1], s[2] + a * v1[2] + b * v2[2]];

    let (mut factor1, mut factor2) = (1.0f64, 1.0f64);
    while !grid.inside(&point(factor1 + 0.0, factor2 + 0.0))? {
        let (shrunk1, shrunk2) = (factor1 * 0.9, factor2 * 0.7);
        if shrunk1 == factor1 && shrunk2 == factor2 {
            return Ok(None);
        }
        factor1 = shrunk1;
        factor2 = shrunk2;
    }
    let (mut v1_n, mut v2_n) = (1.0f64, 0.4f64);
    let (mut f1, mut f2) = (0.0f64, 0.0f64);
    while delta < (v1_n + v2_n) / 2.0 {
        let state = (f1, f2, v1_n, v2_n);
        let mut changed = false;
        if grid.inside(&point(factor1 + (v1_n + f1), factor2 + f2))? {
            f1 += v1_n;
            changed = true;
        }
        if grid.inside(&point(factor1 + f1, factor2 + (f2 + v2_n)))? {
            f2 += v2_n;
            changed = true;
        }
        if !changed {
            v1_n /= 2.0;
            v2_n /= 2.0;
        }
        if (f1, f2, v1_n, v2_n) == state {
            break;
        }
    }
    let out = point(factor1 + f1, factor2 + f2);
    Ok(Some(Array1::from(out.to_vec()).into_dyn().into_pyarray(py).unbind()))
}

